parameters.jsCode:
const gpt = $input.first().json;
const contenu = gpt.choices[0].message.content;
const meta = $('Extraire demande').first().json;

const html = `
<div style="font-family:Georgia,serif;max-width:700px;margin:auto;padding:40px;border:1px solid #ddd">
  <div style="text-align:right;margin-bottom:30px">
    <strong>${meta.organisation}</strong><br/>
    ${new Date().toLocaleDateString('fr-FR',{day:'2-digit',month:'long',year:'numeric'})}
  </div>
  <div style="margin-bottom:20px"><strong>À l'attention de :</strong><br/>${meta.destinataire}</div>
  <div style="margin-bottom:10px"><strong>Objet :</strong> ${meta.objet}</div>
  <hr style="border:1px solid #ccc;margin:20px 0"/>
  <div style="line-height:1.8">${contenu}</div>
  <hr style="border:1px solid #ccc;margin:30px 0"/>
  <div style="font-size:11px;color:#888">
    Réf. ${meta.courrier_id} — Généré par TransferAI Nettelecom CI<br/>
    Ce courrier doit être validé par un responsable avant envoi.
  </div>
</div>`;

const lien_approbation = `https://[VPS_DOMAIN]/webhook/courrier-approve?id=${meta.courrier_id}&decision=approved`;
const lien_refus = `https://[VPS_DOMAIN]/webhook/courrier-approve?id=${meta.courrier_id}&decision=rejected`;

return [{ json: {
  courrier_html: html,
  courrier_brut: contenu,
  courrier_id: meta.courrier_id,
  objet: meta.objet,
  destinataire: meta.destinataire,
  email_validation: meta.email_validation,
  lien_approbation,
  lien_refus
}}];

